// ========= UNIVERSAL BUSINESS SCRAPER — pages from ALL links + image canon =========

// 1) Load input
const html = String($json.data ?? $json.body ?? "");
const enteredUrl = (
  $json.url ??
  $node["Edit Fields1"]?.json?.url ??
  $node["HTTP Request"]?.parameter?.url ??
  ""
).toString().trim();

// 2) utils
function strip(s){ return (s ?? "").toString().replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200D\uFEFF]/g,"").trim(); }
function decode(s){
  if(!s) return "";
  const map = {"&nbsp;":" ","&amp;":"&","&lt;":"<","&gt;":">","&quot;":'"',"&#39;":"'","&#8211;":"–","&#8212;":"—","&#038;":"&"};
  s = s.replace(/(&nbsp;|&amp;|&lt;|&gt;|&quot;|&#39;|&#8211;|&#8212;|&#038;)/g, m=>map[m]||m);
  s = s.replace(/&#(\d+);/g, (_,n)=>String.fromCharCode(parseInt(n,10)));
  s = s.replace(/&#x([0-9a-fA-F]+);/g, (_,h)=>String.fromCharCode(parseInt(h,16)));
  return s.trim();
}
function originFromAnything(v){
  v = (v ?? "").toString().trim().replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200D\uFEFF]/g,"");
  if (/^\{\{\s*\$json\./.test(v)) v = "";
  if (!v) return "";
  try {
    if (!/^https?:\/\//i.test(v)) v = "https://" + v;
    const u = new URL(v);
    return `${u.protocol}//${u.hostname}${u.port?":" + u.port:""}/`;
  } catch {}
  const m = v.match(/^(?:https?:\/\/)?([^\/\s?#]+)/i);
  return m && m[1] ? `https://${m[1]}/` : "";
}
function host(u){ try { return new URL(u).hostname.replace(/^www\./i,""); } catch { return ""; } }
function clean(u){ try { const x = new URL(u); x.hash=""; x.search=""; return x.toString(); } catch { return ""; } }
function absolutize(href, base){
  href = strip(href);
  if (!href || href === "#" || href.startsWith("javascript:") || href.startsWith("mailto:") || href.startsWith("tel:")) return "";
  try {
    if (/^https?:\/\//i.test(href)) return new URL(href).toString();
    if (href.startsWith("//")) return new URL((base || "https://") + href.replace(/^\/\//,"")).toString();
    if (base) return new URL(href, base).toString();
  } catch {}
  return "";
}
function pick(rx){ const m = html.match(rx); return m ? decode(m[1]) : ""; }
function stripTagsKeepText(s){
  s = s.replace(/<!--[\s\S]*?-->/g, " ");
  s = s.replace(/<script[\s\S]*?<\/script>/gi, " ");
  s = s.replace(/<style[\s\S]*?<\/style>/gi, " ");
  s = s.replace(/<noscript[\s\S]*?<\/noscript>/gi, " ");
  s = s.replace(/<(br|hr)\s*\/?>/gi, "\n");
  s = s.replace(/<\/(p|div|section|article|li|h[1-6]|header|footer|main)\s*>/gi, "\n");
  s = s.replace(/<li[^>]*>/gi, "• ");
  s = s.replace(/<[^>]+>/g, " ");
  return s.replace(/\u00A0/g, " ").replace(/[ \t]{2,}/g, " ").replace(/\n{3,}/g, "\n\n").trim();
}
function dedupe(arr){
  const seen = new Set(); const out = [];
  for (const it of arr) { if (!seen.has(it.url)) { seen.add(it.url); out.push(it); } }
  return out;
}

// --- NEW: Canonicalize Jetpack/Photon image URLs (i0.wp.com etc.)
function canonImage(u, targetW=500){
  try{
    const url = new URL(u);
    const isPhoton = /\.wp\.com$/i.test(url.hostname) || /(^|\.)wp\.com$/i.test(url.hostname);
    if (!isPhoton) return u;

    // parse fit/resize -> width
    let w = targetW;
    const fit = url.searchParams.get("fit") || "";
    const resize = url.searchParams.get("resize") || "";
    const wParam = url.searchParams.get("w");
    if (wParam) w = parseInt(wParam,10) || targetW;
    else if (fit && /\d+[,xX]\d+/.test(fit)) w = parseInt(fit.split(/[xX,]/)[0],10) || targetW;
    else if (resize && /\d+[,xX]\d+/.test(resize)) w = parseInt(resize.split(/[xX,]/)[0],10) || targetW;

    // rebuild query: keep ssl=1 if present, set w=
    const hadSSL = url.searchParams.has("ssl") ? url.searchParams.get("ssl") : "1";
    url.search = ""; // wipe existing params
    url.searchParams.set("w", String(w));
    if (hadSSL) url.searchParams.set("ssl", String(hadSSL));
    return url.toString();
  }catch{ return u; }
}

// 3) baseUrl
let baseUrl = originFromAnything(enteredUrl);
if (!baseUrl) {
  const canon = pick(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/i);
  const base  = pick(/<base[^>]*href=["']([^"']+)["']/i);
  const ogurl = pick(/<meta[^>]*property=["']og:url["'][^>]*content=["']([^"']+)["']/i);
  baseUrl = originFromAnything(canon || base || ogurl);
  if (!baseUrl) {
    const anyAbs = (html.match(/https?:\/\/[^"'()<>\s]+/gi) || [])[0];
    baseUrl = originFromAnything(anyAbs);
  }
}
const baseHost = host(baseUrl || enteredUrl);

// 4) collect every href (anchors, permissive href=, raw absolute)
const rawHrefs = new Set();

// A) <a ... href=...>...</a>
{
  const aPairRx = /<a\b([^>]*?)>([\s\S]*?)<\/a>/gi;
  const hrefAttrRx = /href\s*=\s*(?:"([^"]+)"|'([^']+)'|([^'"\s>]+))/i;
  let m;
  while ((m = aPairRx.exec(html))) {
    const attrs = m[1] || "";
    const hm = attrs.match(hrefAttrRx);
    if (!hm) continue;
    rawHrefs.add(hm[1] || hm[2] || hm[3] || "");
  }
}
// B) any href=
{
  const hrefAnyRx = /href\s*=\s*(?:"([^"]+)"|'([^']+)'|([^'"\s>]+))/gi;
  let h; while ((h = hrefAnyRx.exec(html))) rawHrefs.add(h[1] || h[2] || h[3] || "");
}
// C) raw absolute URLs
(html.match(/https?:\/\/[^\s"'<>]+/gi) || []).forEach(u => rawHrefs.add(u));

// 5) resolve & classify
const internal = [];
const external = [];
const relatives = [];

for (const raw of rawHrefs) {
  const abs = absolutize(raw, baseUrl);
  if (!abs) { relatives.push({ text: "", url: raw }); continue; }
  const url = clean(abs); if (!url) continue;
  if (host(url) === baseHost) internal.push({ text: "", url });
  else external.push({ text: "", url });
}

const internalLinks = dedupe(internal);
const externalLinks = dedupe(external);
const relativeLinks = dedupe(relatives);

const navWords = /(home|services?|about|à propos|contact|pricing|tarifs?|plans?|book|booking|reservation|blog|news|portfolio|shop|store|produits?|faq|support|terms|privacy|policy|\/fr\/?$)/i;
const navLinks = internalLinks.filter(it => navWords.test(it.url));

// 6) business signals
const titleTag = pick(/<title[^>]*>([\s\S]*?)<\/title>/i);
const metaDesc = pick(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i) || pick(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["'][^>]*>/i);
const ogTitle  = pick(/<meta[^>]*property=["']og:title["'][^>]*content=["']([^"']+)["']/i);
const ogDesc   = pick(/<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']+)["']/i);
const langAttr = pick(/<html[^>]*lang=["']([a-zA-Z-]+)["']/i) || "";

// ---- build EVERY url set for pages/socials
const everyUrl = Array.from(new Set([
  ...internalLinks.map(x=>x.url),
  ...externalLinks.map(x=>x.url),
  ...relativeLinks.map(x=>absolutize(x.url, baseUrl) || x.url)
].filter(Boolean)));

const findOne = (rx) => (everyUrl.find(u => rx.test(u)) || null);

const pages = {
  home:    findOne(new RegExp(`^${(baseUrl||"").replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}$`)) || baseUrl || null,
  services:findOne(/\/services?\/?$/i),
  about:   findOne(/about-us?|à-propos/i),
  contact: findOne(/contact(-us)?\/?$/i),
  blog:    findOne(/\/(blog|news)\/?$/i),
  pricing: findOne(/\/(pricing|tarifs?|plans?)\/?$/i),
  french:  findOne(/\/fr\/?$/i)
};

// favicon/logo (with image canon)
const guessAsset = (nameRx) => {
  const pool = everyUrl;
  return pool.find(u => nameRx.test(u)) || null;
};
const favicon = (() => {
  const m = html.match(/<link[^>]+rel=["'](?:shortcut icon|icon|mask-icon)["'][^>]*href=["']([^"']+)["']/i);
  const abs = absolutize(m ? m[1] : "", baseUrl);
  const raw = clean(abs) || guessAsset(/favicon\.(ico|png|svg)/i);
  return raw ? canonImage(raw, 64) : null;
})();
const logo = (() => {
  const ogM = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i);
  const abs = absolutize(ogM ? ogM[1] : "", baseUrl);
  const raw = clean(abs) || guessAsset(/logo|og[-_]?image/i);
  return raw ? canonImage(raw, 500) : null;   // << w=500
})();

// cms
const cmsHint = (() => {
  const h = html.toLowerCase();
  if (/wp-content|wp-includes|jetpack|wordpress/i.test(h)) return "WordPress";
  if (/woocommerce/i.test(h)) return "WooCommerce (WordPress)";
  if (/shopify|cdn\.shopify|cart\/add/i.test(h)) return "Shopify";
  if (/squarespace\.com|sqs-/i.test(h)) return "Squarespace";
  if (/wixstatic\.com/i.test(h)) return "Wix";
  return "";
})();

// contacts
const textForPlain = stripTagsKeepText(html);
const emailsOut = Array.from(new Set([
  ...[...html.matchAll(/mailto:([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/gi)].map(m=>m[1].toLowerCase()),
  ...[...textForPlain.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)].map(m=>m[0].toLowerCase())
])).slice(0, 10);
const phonesOut = Array.from(new Set([
  ...[...html.matchAll(/tel:([+0-9()[\]\s.-]+)/gi)].map(m=>(m[1]||"").replace(/[^\d+]/g,"")),
  ...[...textForPlain.matchAll(/(\+?\d[\d\s().-]{8,}\d)/g)].map(m=>(m[1]||"").replace(/[^\d+]/g,""))
].filter(n => n.length>=10 && n.length<=15))).slice(0, 10);

// socials from everyUrl
const socials = {
  instagram: everyUrl.filter(u=>/instagram\.com\//i.test(u)).slice(0,5),
  linkedin:  everyUrl.filter(u=>/linkedin\.com\//i.test(u)).slice(0,5),
  tiktok:    everyUrl.filter(u=>/tiktok\.com\//i.test(u)).slice(0,5),
  facebook:  everyUrl.filter(u=>/facebook\.com\//i.test(u)).slice(0,5),
  youtube:   everyUrl.filter(u=>/youtu(\.be|be\.com)/i.test(u)).slice(0,5),
  x:         everyUrl.filter(u=>/(x\.com|twitter\.com)\//i.test(u)).slice(0,5),
};

// business name/desc
const businessName = (ogTitle || titleTag || "").split(" | ")[0].split(" – ")[0].trim()
                   || (host(baseUrl).split(".")[0] || "(no title)");
const description  = ogDesc || metaDesc || "";

// 7) Output
return [{
  json: {
    enteredUrl: enteredUrl || "(not provided)",
    baseUrl: baseUrl || "(unknown)",
    internalLinks: internalLinks.slice(0, 200),
    navLinks: navLinks.slice(0, 50),
    externalLinks: externalLinks.slice(0, 100),
    relativeLinks: relativeLinks.slice(0, 200),
    businessCard: {
      name: businessName,
      description,
      language: (pick(/<html[^>]*lang=["']([a-zA-Z-]+)["']/i) || null),
      favicon,
      logo,                   // <- now canonicalized to ?w=500&ssl=1 when Jetpack
      cms: cmsHint || null,
      contacts: { emails: emailsOut, phones: phonesOut },
      socials,
      pages                   // <- now built from ALL links (includes your relativeLinks)
    }
  }
}];
